import{_ as t,o as l,c as p,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"July 2019 :: Ceph Developer Monthly","description":"","frontmatter":{"title":"July 2019 :: Ceph Developer Monthly","date":"2019-07-22T00:00:00.000Z","updated":"2019-07-22T00:00:00.000Z","tags":["Ceph","分布式存储","监控优化","网络监控","健康警报"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/July_2019_-_-_Ceph_Developer_Monthly.md","filePath":"posts/2019/July_2019_-_-_Ceph_Developer_Monthly.md","lastUpdated":1780459816000}'),_={name:"posts/2019/July_2019_-_-_Ceph_Developer_Monthly.md"};function r(s,e,n,i,a,h){return l(),p("div",null,[...e[0]||(e[0]=[o("<p>在2019年7月的CD Emma会议上，Ceph存储系统的研发人员和内容审核专家讨论了多个监控和优化方面的议题。以下是对会议内容的总结：</p><p><strong>会议主题</strong>： Ceph存储系统监控与优化</p><p><strong>关键内容</strong>：</p><ul><li><strong>减少延迟时间</strong>： David介绍了用于检测慢速网络连接性的工具，包括设置警告级别和不同时间间隔的平均ping时间来识别网络问题。讨论了使用最大ping时间而不是平均ping时间的可行性，以及如何处理心跳接口的重置情况。</li><li><strong>健康警报</strong>： 讨论了使用“静音”功能来处理健康警报，包括设置静音时间、匹配模式、匹配规则等，以及如何处理不同类型的健康警报，例如OSD失败、性能下降等。</li><li><strong>请求诊断</strong>： 讨论了改进请求诊断的方法，例如记录更详细的日志、生成更清晰的错误消息、收集更多指标等，以及如何处理磁盘忙、I/O错误、CPU负载过高等问题。</li><li><strong>其他议题</strong>： 讨论了使用脚本分析集群日志和性能数据的方法，以及在仪表板中提供历史视图和热图的功能，以及收集和存储崩溃转储文件的方法，以及向Ceph集群添加“通道”概念，以便更灵活地启用或禁用不同类型的遥测数据。</li></ul><p><strong>行动计划</strong>：</p><ul><li>David将修改代码，并提交一个包含上述功能的pull request。</li><li>其他参会人员将审查pull request，并提供反馈。</li><li>根据反馈，进一步改进功能。</li><li>将功能集成到Ceph存储系统中。</li></ul><p>本次会议讨论了Ceph存储系统监控和优化的多个方面，包括网络监控、健康警报、请求诊断、崩溃转储文件收集等，并确定了行动计划，以提升Ceph存储系统的性能和可用性。</p>",7)])])}const d=t(_,[["render",r]]);export{g as __pageData,d as default};
